'use strict';
const UI={view:'start',tab:'home',sel:null,comp:'table',tr:'market',trPos:'ALL',fixR:null,modal:null,match:null,msg:null,pick:null,mgr:'',boxSide:0,ldr:'pts'};

/* ===================== Small components ===================== */
const SHAPES=['M50 4 L92 20 V66 C92 94 72 110 50 120 C28 110 8 94 8 66 V20Z','M10 8 H90 V64 C90 94 70 110 50 120 C30 110 10 94 10 64Z','M50 4 L94 26 V78 L50 120 L6 78 V26Z'];
const LOGO=t=>(window.LOGOS||{})[t.short];
// on dark backgrounds (class 'dk') clubs with a dark logo use their white version
const LOGOW=t=>(window.LOGOS_DARK||{})[t.short]||LOGO(t);
function crest(t,cls=''){if(t&&t.nt&&window.NT_FLAGS&&NT_FLAGS[t.nt])return `<img class="crest ${cls}" src="${NT_FLAGS[t.nt]}" alt="" style="object-fit:contain">`;if(LOGO(t))return `<img class="crest logo ${cls}" src="${/\bdk\b/.test(cls)?LOGOW(t):LOGO(t)}" alt="">`;const d=SHAPES[t.id%3],tc=tcol(t),sz=t.short.length>3?26:31;
  return `<svg class="crest ${cls}" viewBox="0 0 100 124" aria-hidden="true"><path d="${d}" fill="${t.c1}" stroke="${t.c2}" stroke-width="5" stroke-linejoin="round"/><path d="${d}" transform="translate(9 11) scale(.82)" fill="none" stroke="${tc}" stroke-opacity=".45" stroke-width="2.4"/><path d="${d}" fill="url(#gl)"/><path d="M50 26 l3 6.4 7 .6-5.3 4.6 1.6 6.8L50 40.8l-6.3 3.6 1.6-6.8L40 33l7-.6z" fill="${tc}" opacity=".9"/><text x="50" y="84" text-anchor="middle" font-family="Barlow Condensed,Arial Narrow,sans-serif" font-weight="900" font-size="${sz}" fill="${tc}" letter-spacing="1">${t.short}</text></svg>`;}
const mini=t=>LOGO(t)?`<img class="mini logo" src="${LOGO(t)}" alt="">`:`<span class="mini" style="background:${t.c1};color:${tcol(t)}">${t.short}</span>`;
// never show a portrait of a minor, even if a generated youngster shares a real player's name
const PH=p=>{const v=p&&p.age!=null&&p.age<18?null:(window.PHOTOS||{})[p.phk||pname(p)];return v?{sheet:window.SPRITES.p[v[0]],t:v[1]}:null;};
const spr=(o,alt)=>{const n=(window.SHEET_N||{})[o.sheet]||10;return `<span class="sp" role="img" aria-label="${esc(alt)}" style="background-image:url(${o.sheet});${n!==10?`background-size:${n*100}% ${n*100}%;`:''}background-position:${(o.t%n)*100/(n-1)}% ${Math.floor(o.t/n)*100/(n-1)}%"></span>`;};
const SIL=txt=>`<svg viewBox="0 0 100 100" aria-hidden="true"><rect width="100" height="100" fill="#eef0f3"/><circle cx="50" cy="37" r="17" fill="#c5cbd3"/><path d="M12 104C14 74 31 61 50 61S86 74 88 104Z" fill="#c5cbd3"/><text x="50" y="92" text-anchor="middle" font-family="Barlow Condensed,Arial Narrow,sans-serif" font-weight="800" font-size="22" fill="#ffffff">${txt}</text></svg>`;
// players without a photo: a drawn silhouette in their club's jersey with the shirt number (no real face)
const JSIL=(p,txt)=>{const t=p&&p.tid!=null&&G&&G.teams[p.tid];return t?JSILt(t,txt):SIL(txt);};
const JSILt=(t,txt)=>{const c1=/^#[0-9a-f]{6}$/i.test(t.c1)?t.c1:'#1f3b73',tc=tcol(t),c2=/^#[0-9a-f]{6}$/i.test(t.c2)&&t.c2.toLowerCase()!==c1.toLowerCase()?t.c2:tc;
  return `<svg viewBox="0 0 100 100" aria-hidden="true"><rect width="100" height="100" fill="#eef0f3"/><rect width="100" height="100" fill="${c1}" opacity=".12"/><path d="M41 52h18v12H41z" fill="#b7bec8"/><ellipse cx="50" cy="35" rx="15" ry="17.5" fill="#c3c9d2"/><path d="M35 31c1-11 8-16 15-16s14 5 15 16c-3-5-8-7-15-7s-12 2-15 7z" fill="#a9b1bc"/><path d="M8 104c1-25 11-36 26-41l6 4c2 4 6 6 10 6s8-2 10-6l6-4c15 5 25 16 26 41z" fill="${c1}"/><path d="M34 63l6 4c2 4 6 6 10 6s8-2 10-6l6-4" fill="none" stroke="${c2}" stroke-width="3.2" stroke-linejoin="round"/><path d="M27 66c-2 9-2 21-1 38M73 66c2 9 2 21 1 38" stroke="${c2}" stroke-width="2.2" fill="none" opacity=".8"/><text x="50" y="95" text-anchor="middle" font-family="Barlow Condensed,Arial Narrow,sans-serif" font-weight="900" font-size="21" fill="${tc}">${txt}</text></svg>`;};
const avatarIn=(p,txt)=>PH(p)?spr(PH(p),pname(p)):JSIL(p,txt);
const photoCredit=p=>'';
// stats of a player's main league: ABA for clubs that only play the ABA League
const mst=p=>{const t=p.tid!=null&&G.teams[p.tid];if(t&&t.dom==='CUP')return p.est||blank();return t&&(t.dom==='KLS'||t.dom==='BIH'||NLCFG[t.dom])?(p.kst||blank()):t&&t.dom?(p.dst||blank()):p.st;};
const ovc=o=>o>=85?'o1':o>=78?'o2':o>=70?'o3':o>=62?'o4':'o5';
const ovb=o=>`<span class="ovr ${ovc(o)}">${o}</span>`;
const form=f=>`<span class="fm">${f.map(x=>`<span class="${x}">${x}</span>`).join('')}</span>`;
const ecol=e=>e>=80?'var(--g)':e>=60?'var(--y)':'var(--r)';
const ebar=e=>`<span class="eb" title="Energy ${Math.round(e)}%${e<65?` \u00b7 injury risk \u00d7${fatigueRisk(e)}`:''}"><i style="width:${e}%;background:${ecol(e)}"></i></span>`;
// Long grey explainer paragraphs move out of the card body into a panel behind an "i" in the card header.
let infN=0;
function infSplit(body){if(typeof body!=='string'||!/class="(?:mut|cb mut|sec mut)"/.test(body))return [body,''];const out=[];
  const b=body.replace(/<(p|div) class="(?:mut|cb mut|sec mut)"[^>]*>((?:(?!<div|<p[ >])[\s\S])*?)<\/\1>/g,(m,tg,t,off)=>{
    if(/class="(neg|pos|pill|btn)|data-act|<input|<select|<button/.test(t))return m;
    if(t.replace(/<[^>]+>/g,'').length<110)return m;
    const pre=body.slice(Math.max(0,off-400),off),e=pre.lastIndexOf('class="empty"');if(e>=0&&pre.indexOf('</div>',e)<0)return m;
    out.push(t);return '';});
  if(!out.length)return [body,''];
  const b2=b.replace(/<div class="(?:sec|cb)"[^>]*>\s*<\/div>/g,'');
  if(!b2.replace(/<[^>]+>/g,'').trim()&&b2.indexOf('<svg')<0&&b2.indexOf('<img')<0&&b2.indexOf('<canvas')<0)return [body,''];
  return [b2,out.map(t=>`<p>${t}</p>`).join('')];}
const card=(title,body,link)=>{const [b,inf]=infSplit(body),id=inf?'inf'+(++infN):'';
  return `<section class="card"><div class="ch"><h3>${title}${inf?`<label class="inf" for="${id}" title="How this works">i</label>`:''}</h3>${link||''}</div>${inf?`<input type="checkbox" class="inf-c" id="${id}" aria-label="Show how this works"><div class="inf-p">${inf}</div>`:''}${b}</section>`;};
const lnk=(act,txt)=>`<button class="lnk" data-act="${act}">${txt} \u203a</button>`;
const ht=cm=>(cm/100).toFixed(2)+' m';
const status=p=>(p.tid===G.user&&G.captain===p.id?'<span class="pill k">C</span> ':'')+(p.rest&&p.tid===G.user?'<span class="pill b">Rest</span> ':'')+status0(p);
const status0=p=>p.ten&&p.tid===G.user?`<span class="pill o">10-day \u00b7 ${Math.max(0,p.ten.until-G.day)}d</span>`:p.tid===G.user&&forBenched(G.user).includes(p)?`<span class="pill r">Not eligible</span>`:p.short&&p.tid===G.user?`<span class="pill o">${p.short.k==='jk'?'Joker':'Short-term'}</span>`:p.loan?`<span class="pill o">${p.loan.gl?(p.loan.from===G.user?'G League':p.tw?'Two-way':'NBA assignee'):'On loan'}</span>`:p.unhappy?`<span class="pill r">Unhappy</span>`:p.inj>0?`<span class="pill r">Injured \u00b7 ${p.inj}</span>`:G.listed.includes(p.id)?`<span class="pill b">Listed</span>`:p.energy<65?`<span class="pill y">Tired</span>`:p.fragile?`<span class="pill y">Fragile</span>`:`<span class="pill g">Fit</span>`;
const IC={
  inbox:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><path d="M3 6h18v12H3z"/><path d="M3 7l9 6 9-6"/></svg>',
  med:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6z"/></svg>',
  scout:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="11" cy="11" r="6.5"/><path d="M16 16l5 5" stroke-linecap="round"/></svg>',
  ball:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M5.6 5.6c3.5 3 3.5 9.8 0 12.8M18.4 5.6c-3.5 3-3.5 9.8 0 12.8M3 12h18"/></svg>',
  save:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><path d="M5 3h11l3 3v15H5z"/><path d="M8 3v5h7V3M8 21v-7h8v7"/></svg>',
  arrow:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 4l8 8-8 8"/></svg>',
};
const MI={res:['var(--g)','\u2713'],med:['var(--r)','+'],offer:['var(--or)','\u20ac'],fin:['#7a5af0','\u20ac'],board:['var(--ink3)','B'],staff:['var(--b)','C'],job:['var(--g)','J']};
