function homeHTML(){return todoHTML()+`<div class="g-home"><div class="stack">${preCard()}${nextMatchCard()}${isCol(G.teams[G.user])?nilHome()+ncBracketCard()+apCard():''}${fixturesCard()}${resultsCard()}${rumourCard()}${feedCard()}</div><div class="stack">${pokCard()}${standingsCard()}</div><div class="stack">${inboxCard()}${spotlightCard()}${boardCard()}</div></div>`;}
function h2hGames(a,b,kind){return (isFecK(kind)&&G.fec?G.fec.res:isBclK(kind)&&G.bcl?G.bcl.res:isEcK(kind)&&G.ec?G.ec.res:isNlK(kind)&&nlOf(a)?nlOf(a).res:isBihK(kind)&&G.bih?G.bih.res:isKlsK(kind)&&G.kls?G.kls.res:isD2K(kind)&&G.dom2?G.dom2.res:isDomK(kind)&&G.dom?G.dom.res:G.res).filter(r=>(r[0]===a&&r[1]===b)||(r[0]===b&&r[1]===a));}
