function fxContext(f){if(f.kind==='pre')return preLabel(f.pre);if(f.ref==='aq'&&G.aq){const A=G.aq;return `Promotion/relegation series \u00b7 ${G.teams[A.aba].short} ${A.wa}\u2013${A.wb} ${G.teams[A.a2].short} \u00b7 best of 3 for a place in the ABA League`;}const D=G.dom,D2=G.dom2,K=G.kls,B=G.bih;if(f.kind==='fec')return f.st==='r2'?`Europe Cup Second Round \u00b7 Group ${fecGroupOf(f.h,true)}`:`Europe Cup Group ${fecGroupOf(f.h)} \u00b7 regular season`;if(f.kind==='fecpo'){const F=G.fec,s=F.po.ser[f.ref];return `Europe Cup ${FECSTAGE[F.po.stage].toLowerCase()} \u00b7 ${s.n===0?'first leg':`second leg \u00b7 aggregate ${G.teams[s.hi].short} ${s.ph}\u2013${s.pl} ${G.teams[s.lo].short}`}`;}if(f.kind==='bcl'){const B=G.bcl;return f.st==='r16'?`Champions League Round of 16 \u00b7 Group ${bclGroupOf(f.h,true)}`:`Champions League Group ${bclGroupOf(f.h)} \u00b7 regular season`;}if(f.kind==='bclpo'){const B=G.bcl,s=B.po.ser[f.ref];return s.need>1?`Champions League ${BCLSTAGE[B.po.stage].toLowerCase()} \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of 3`:`Champions League ${BCLSTAGE[B.po.stage]} \u00b7 neutral court`;}if(f.kind==='ec'){const E=G.ec;return `EuroCup Group ${ecGroupOf(f.h)} \u00b7 ${E.rounds.length-E.round-1} group rounds left after this one`;}if(f.kind==='ecpo'){const E=G.ec,s=E.po.ser[f.ref];return `EuroCup ${ECSTAGE[E.po.stage].toLowerCase()} \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of 3`;}if(f.kind==='nl'){const L=G.nl[f.lg],C=NLCFG[L.code];return `${L.groups&&G.teams[f.h].grp?`${C.short} ${G.teams[f.h].grp} \u00b7 `:''}${L.sched.length-L.round-1} ${C.short} rounds left after this one`;}if(f.kind==='nlpo'){const L=G.nl[f.lg],C=NLCFG[L.code],s=L.po.ser[f.ref];return s.agg?`${C.short} ${L.code==='PROA'?'finals':nlStName(L,L.po.stage).toLowerCase()} \u00b7 ${s.n===0?'first leg':`second leg \u00b7 aggregate ${G.teams[s.hi].short} ${s.ph}\u2013${s.pl} ${G.teams[s.lo].short}`}`:s.need>1?`${C.short} ${nlStName(L,L.po.stage).toLowerCase()} \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of ${s.need*2-1}`:`${C.short} ${nlStName(L,L.po.stage).toLowerCase()} \u00b7 single game`;}if(f.kind==='bihpo'){const s=B.po.ser[f.ref];return s.agg?`Prvenstvo BiH ${BIHSTAGE[B.po.stage].toLowerCase()} \u00b7 two legs on aggregate \u00b7 ${s.n===0?'first leg':`aggregate ${G.teams[s.hi].short} ${s.ph}\u2013${s.pl} ${G.teams[s.lo].short}`}`:`Prvenstvo BiH final \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of 3`;}if(f.kind==='klspo'){const s=K.po.ser[f.ref];return s.need>1?`KLS Super League quarter-final \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of 3`:`KLS ${KLSSTAGE[K.po.stage]} \u00b7 single game \u00b7 neutral venue`;}if(f.kind==='kls')return `${K.sched.length-K.round-1} First League rounds left`;if(f.kind==='bih')return `${B.sched.length-B.round-1} Liga 14 rounds left`;if(f.kind==='d2')return `Group ${dom2GroupOf(f.h)} \u00b7 ${D2.sched.length-D2.round-1} group rounds left after this one`;if(f.kind==='d2po'){const s=D2.po.ser[f.ref];return s.need>1?`ABA League 2 ${DOM2STAGE[D2.po.stage].toLowerCase()} \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of 3`:'ABA League 2 Play-In \u00b7 single game';}if(f.kind==='dom')return D.top8?`${D.top8.includes(f.h)?'Top 8':'Play-Out'} \u00b7 ${D.sched.length-D.round-1} rounds left after this one`:`${D.groups.A.includes(f.h)?'Group A':'Group B'} \u00b7 ${D.n1-D.round-1} group rounds left after this one`;if(f.kind==='dpo'){const s=D.po.ser[f.ref];return s.need>1?`ABA ${DOMSTAGE[D.po.stage].toLowerCase()} \u00b7 series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of ${s.need*2-1}`:`ABA ${DOMSTAGE[D.po.stage].toLowerCase()} \u00b7 single game${D.po.stage==='pi1'&&f.ref===0?' \u00b7 the loser gets a second chance':''}`;}if(f.kind==='po'){const s=G.po.qf[f.ref];return `Series ${G.teams[s.hi].short} ${s.wh}\u2013${s.wl} ${G.teams[s.lo].short} \u00b7 best of five`;}if(f.kind==='pi')return 'Single game \u00b7 loser is eliminated';if(f.kind==='f4')return 'Semi-final \u00b7 single game';if(f.kind==='fin')return 'Championship game';return `${G.schedule.length-G.round-1} rounds left after this one`;}
