function ntFive(c){let pool=[];try{pool=ntPool(c).slice(0,24);}catch(e){return [];}const out=[];
  for(const pos of ['PG','SG','SF','PF','C']){const p=pool.find(x=>!out.includes(x)&&x.pos===pos);if(p)out.push(p);}
  for(const p of pool){if(out.length>=5)break;if(!out.includes(p))out.push(p);}
  const ord={PG:0,SG:1,SF:2,PF:3,C:4};return out.slice(0,5).sort((x,y)=>(ord[x.pos]??5)-(ord[y.pos]??5));}
