  const card=(p,i)=>{const t=tm(p),o=ovrEst(p);return `<div class="ntp${i<5&&st!=='pre'?' st':''}"><button class="ntp-x" data-act="ntpick:${p.id}" title="Remove">×</button>${i<5&&st!=='pre'?'<i class="ntp-s">Starter</i>':''}<span class="ntp-mv"><button data-act="ntmv:${p.id}:-1" title="Earlier">‹</button><button data-act="ntmv:${p.id}:1" title="Later">›</button></span><div class="ntp-ph">${avatarIn(p,p.no)}</div><span class="ntr ${rc(o)}">${o}</span><b class="click" data-act="prof:${p.id}">${esc(p.l||pname(p))}</b><small>${esc(p.f||'')}</small><small class="ntp-m">${p.pos} · ${p.age}</small><small class="ntp-c">${t?`${mini(t)}${esc(t.short)}`:esc(p.ntClub||'Free agent')}</small><div class="ntp-t">${tags(p)}</div></div>`;};
