function ntStaffHTML(){const J=G.nt.job,c=J.c,S=ntStaffGet(),F=UI.ntsf||(UI.ntsf={role:'AC',src:'all',nat:'all'}),q=(UI.ntSQ||'').trim().toLowerCase();
  const rc=o=>o>=85?'r1':o>=78?'r2':o>=70?'r3':o>=62?'r4':'r5',fl=n=>window.NT_FLAGS&&window.NT_FLAGS[n]?ntFlag(n,18):'',tn=tid=>tid!=null&&G.teams[tid]?G.teams[tid]:null;
  const slot=(x,k,i,lbl)=>x?`<div class="nts-c"><span class="nts-ph">${sAvatar(x)}</span><div class="nts-t"><small>${lbl}</small><b>${esc(x.f+' '+x.l)}</b><em>${fl(x.nat)} ${esc(x.nat||'–')}${tn(x.tid)?` · also at ${esc(tn(x.tid).name)}`:''}</em></div><span class="ntr ${rc(x.o)}">${x.o}</span><button class="nts-x" data-act="ntsfire:${k}:${i}">Release</button></div>`
    :`<button class="nts-c empty" data-act="ntsrole:${k==='ac'?'AC':'DOC'}"><span class="nts-ph">+</span><div class="nts-t"><small>${lbl}</small><b>Open position</b><em>Hire from the market below</em></div></button>`;
  const pool=ntStaffPool().filter(({st,tid})=>(F.role==='AC'?ntSRole(st)==='ac':st.role==='DOC')&&(F.src==='all'||(F.src==='fa')===(tid==null))&&(F.nat==='all'||st.nat===c)&&(!q||(st.f+' '+st.l).toLowerCase().includes(q))).sort((a,b)=>ntSRate(b.st)-ntSRate(a.st));
  const on=S.ac.concat([S.doc]).filter(Boolean).map(x=>x.sid),total=pool.length,list=UI.ntsAll?pool:pool.slice(0,50);
  const ip=v=>v>=70?['g','Very keen']:v>=50?['g','Interested']:v>=35?['y','Open to talks']:['r','Not interested'];
  const row=({st,tid})=>{const iv=ntStaffInt(st),[pc,pl]=ip(iv),t=tn(tid),mine=on.includes(st.id),full=ntSRole(st)==='ac'?S.ac.length>=2:!!S.doc;
    return `<tr class="${iv<35?'off':''}"><td class="ntl-ph">${sAvatar(st)}</td><td><b>${esc(st.f+' '+st.l)}</b><small>${st.role==='HC'?'Head coach, would assist':ROLEN[st.role]} · ${st.age} yrs · ${t?`${mini(t)}${esc(t.name)}`:'Free agent'}${st.from?` · ex ${esc(st.from)}`:''}</small></td><td>${fl(st.nat)} ${esc(st.nat||'–')}</td><td class="mut" style="font-size:12.5px">${Object.keys(st.r).map(k=>`${RATN[k]} <b>${st.r[k]}</b>`).join(' · ')}</td><td class="n"><span class="ntr ${rc(ntSRate(st))}">${ntSRate(st)}</span></td><td><span class="pill ${pc}">${pl}</span></td><td class="r">${mine?'<span class="pill g">On your staff</span>':`<button class="ntl-b" data-act="ntshire:${st.id}" ${iv<35||full?'disabled':''} title="${full?'Position filled: release someone first':''}">Hire</button>`}</td></tr>`;};
  const seg=(k,opts)=>`<div class="seg">${opts.map(([v,l])=>`<button class="${F[k]===v?'on':''}" data-act="ntsf:${k}:${v}">${l}</button>`).join('')}</div>`;
  return `<section class="ntc"><div class="ntc-h"><div><small>National team staff</small><b>${esc(ntName(c))} · your staff</b><span>Assistant coaches raise the team's level in games (the best counts fully, the second half). The doctor lowers the injury risk on international duty. The federation pays; staff at clubs keep their club job.</span></div><div class="ntc-n"><b>+${ntCoachBonus().toFixed(1)}</b><small>coaching bonus</small></div></div>
  <div class="nts">${slot(S.ac[0],'ac',0,'Assistant coach 1')}${slot(S.ac[1],'ac',1,'Assistant coach 2')}${slot(S.doc,'doc',0,'Team doctor')}</div></section>
  <section class="ntc"><div class="ntc-h"><div><small>Staff market</small><b>${F.role==='AC'?'Assistant coaches':'Team doctors'} · every nationality</b><span>${total} people${q||F.src!=='all'||F.nat!=='all'?' match the filter':''}. Free agents and staff at clubs around the world.</span></div></div>
    <div class="ntf">${seg('role',[['AC','Assistant coaches'],['DOC','Team doctors']])}${seg('src',[['all','All'],['fa','Free agents'],['club','At clubs']])}${seg('nat',[['all','Any nationality'],[c,`${ntName(c)} only`]])}<input id="ntSQ" placeholder="Search a name" value="${esc(UI.ntSQ||'')}"></div>
    <div class="tw"><table class="ntl nts-l"><thead><tr><th></th><th>Name</th><th>Nat.</th><th>Ratings</th><th class="n">Rating</th><th>Interest</th><th></th></tr></thead><tbody>${list.map(row).join('')||'<tr><td colspan="7" class="mut">Nobody matches the filter.</td></tr>'}</tbody></table></div>
    ${total>50?`<div class="ntc-a"><button data-act="ntsall">${UI.ntsAll?'Show top 50':`Show all ${total}`}</button></div>`:''}</section>`;}
